import numpy as np
import pyswarms as ps
import json
import re

from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message


class PSOConsensusComponent(Component):
    display_name = "PSO Consensus Engine"
    description = "Optimiza pesos de agentes usando PySwarms GlobalBestPSO (50 partículas, 100 iter.)"
    icon = "cpu"
    name = "PSOConsensusComponent"

    inputs = [
        MessageTextInput(name="agente_tecnico", display_name="Señal Agente Técnico"),
        MessageTextInput(name="agente_commodities", display_name="Señal Agente Commodities"),
        MessageTextInput(name="agente_sentimiento", display_name="Señal Agente Sentimiento"),
        MessageTextInput(name="agente_riesgo", display_name="Señal Agente Riesgo"),
    ]

    outputs = [
        Output(display_name="PSO Result", name="message_output", method="run_pso")
    ]

    def normalizar_texto(self, entrada) -> str:
        """
        Convierte cualquier entrada de Langflow a texto.
        Puede recibir string, Message, dict u otros objetos.
        """
        if entrada is None:
            return ""

        if isinstance(entrada, dict):
            return json.dumps(entrada, ensure_ascii=False)

        if hasattr(entrada, "text"):
            return str(entrada.text)

        if hasattr(entrada, "content"):
            return str(entrada.content)

        if hasattr(entrada, "data"):
            try:
                return json.dumps(entrada.data, ensure_ascii=False)
            except Exception:
                return str(entrada.data)

        return str(entrada)

    def extraer_json(self, entrada) -> dict:
        """
        Extrae JSON desde la salida de un agente.
        Acepta JSON puro o texto que contenga un JSON dentro.
        """
        texto = self.normalizar_texto(entrada).strip()

        if not texto:
            return {}

        # Intento 1: parsear directamente como JSON
        try:
            return json.loads(texto)
        except Exception:
            pass

        # Intento 2: extraer el primer bloque entre { ... }
        match = re.search(r"\{.*\}", texto, re.DOTALL)
        if match:
            try:
                return json.loads(match.group())
            except Exception:
                return {}

        return {}

    def senal_a_valor(self, senal: str) -> float:
        """
        Convierte COMPRAR / MANTENER / VENDER a valor numérico.
        """
        senal = str(senal).upper().strip()

        if senal == "COMPRAR":
            return 1.0
        elif senal == "VENDER":
            return -1.0
        elif senal == "MANTENER":
            return 0.0

        return 0.0

    def procesar_agente(self, entrada, nombre_agente: str) -> dict:
        """
        Procesa la salida de cada agente.
        Prioriza score si existe.
        Si no hay score, usa senal/señal.
        """
        data = self.extraer_json(entrada)
        texto = self.normalizar_texto(entrada)

        agente = data.get("agente", nombre_agente)
        ticker = data.get("ticker", "")

        # Acepta "senal" sin tilde y "señal" con tilde
        senal = data.get("senal", data.get("señal", "MANTENER"))

        # Prioridad 1: usar score si existe
        try:
            score = float(data.get("score"))
        except Exception:
            score = self.senal_a_valor(senal)

        # Limitar score a rango [-1, 1]
        score = max(-1.0, min(1.0, score))

        # Confianza
        try:
            confianza = float(data.get("confianza", 0.5))
        except Exception:
            confianza = 0.5

        # Si confianza viene como porcentaje, convertir a 0-1
        if confianza > 1:
            confianza = confianza / 100.0

        confianza = max(0.0, min(1.0, confianza))

        datos_usados = data.get("datos_usados", "")
        justificacion = data.get("justificacion", data.get("razon", ""))

        # Fallback si el JSON no pudo leerse
        if not data:
            texto_upper = texto.upper()

            if "COMPRAR" in texto_upper:
                senal = "COMPRAR"
                score = 1.0
            elif "VENDER" in texto_upper:
                senal = "VENDER"
                score = -1.0
            else:
                senal = "MANTENER"
                score = 0.0

            confianza = 0.5
            datos_usados = "No se pudo extraer JSON estructurado"
            justificacion = "Se aplicó lectura de respaldo desde texto."

        return {
            "agente": agente,
            "ticker": ticker,
            "senal": senal,
            "score": score,
            "confianza": confianza,
            "datos_usados": datos_usados,
            "justificacion": justificacion,
        }

    def run_pso(self) -> Message:
        agentes = [
            self.procesar_agente(self.agente_tecnico, "tecnico"),
            self.procesar_agente(self.agente_commodities, "commodities"),
            self.procesar_agente(self.agente_sentimiento, "sentimiento"),
            self.procesar_agente(self.agente_riesgo, "riesgo"),
        ]

        scores = np.array([agente["score"] for agente in agentes], dtype=float)
        confianzas = np.array([agente["confianza"] for agente in agentes], dtype=float)

        # Evitar que todas las confianzas sean cero
        if confianzas.sum() == 0:
            confianzas = np.array([0.25, 0.25, 0.25, 0.25], dtype=float)
        else:
            confianzas = confianzas / confianzas.sum()

        def objective_function(particles):
            costs = []

            for particle in particles:
                pesos = np.abs(particle)

                if pesos.sum() == 0:
                    pesos = np.array([0.25, 0.25, 0.25, 0.25])
                else:
                    pesos = pesos / pesos.sum()

                score_pso = np.dot(pesos, scores)

                # Penaliza que los pesos se alejen mucho de las confianzas
                confianza_penalty = np.sum((pesos - confianzas) ** 2)

                # Favorece distribución no extremadamente concentrada
                entropia = -np.sum(pesos * np.log(pesos + 1e-10))
                desbalance_penalty = -entropia

                # Penaliza decisiones extremas cuando hay señales enfrentadas
                senales_activas = np.abs(scores) > 0.1
                if senales_activas.sum() > 1:
                    hay_positivas = (scores[senales_activas] > 0).sum() > 0
                    hay_negativas = (scores[senales_activas] < 0).sum() > 0

                    if hay_positivas and hay_negativas and abs(score_pso) > 0.7:
                        coherencia_penalty = abs(score_pso) * 2
                    else:
                        coherencia_penalty = 0
                else:
                    coherencia_penalty = 0

                cost = (
                    confianza_penalty * 0.4 +
                    desbalance_penalty * 0.3 +
                    coherencia_penalty * 0.3
                )

                costs.append(cost)

            return np.array(costs)

        options = {
            "c1": 0.5,
            "c2": 0.3,
            "w": 0.9,
        }

        bounds = (
            np.zeros(4),
            np.ones(4),
        )

        optimizer = ps.single.GlobalBestPSO(
            n_particles=50,
            dimensions=4,
            options=options,
            bounds=bounds,
        )

        cost, best_pos = optimizer.optimize(
            objective_function,
            iters=100,
            verbose=False,
        )

        pesos_optimos = np.abs(best_pos)

        if pesos_optimos.sum() == 0:
            pesos_optimos = np.array([0.25, 0.25, 0.25, 0.25])
        else:
            pesos_optimos = pesos_optimos / pesos_optimos.sum()

        score_final = float(np.dot(pesos_optimos, scores))

        if score_final >= 0.25:
            decision = "COMPRAR"
        elif score_final <= -0.25:
            decision = "VENDER"
        else:
            decision = "MANTENER"

        # Confianza final ponderada por los pesos óptimos
        confianza_final = float(np.dot(pesos_optimos, np.array([a["confianza"] for a in agentes])))
        confianza_final = max(0.0, min(1.0, confianza_final))

        tickers = [a["ticker"] for a in agentes if a["ticker"]]
        ticker_final = tickers[0] if tickers else "DESCONOCIDO"

        resultado = {
            "motor": "PSO Consensus Engine",
            "algoritmo": "PySwarms GlobalBestPSO",
            "configuracion": {
                "particulas": 50,
                "iteraciones": 100,
                "dimensiones": 4,
            },
            "ticker": ticker_final,
            "senal_final": decision,
            "score_final": round(score_final, 4),
            "confianza_final": round(confianza_final, 4),
            "pesos_optimos": {
                "tecnico": round(float(pesos_optimos[0]), 4),
                "commodities": round(float(pesos_optimos[1]), 4),
                "sentimiento": round(float(pesos_optimos[2]), 4),
                "riesgo": round(float(pesos_optimos[3]), 4),
            },
            "agentes": {
                "tecnico": agentes[0],
                "commodities": agentes[1],
                "sentimiento": agentes[2],
                "riesgo": agentes[3],
            },
            "costo_optimizacion": round(float(cost), 6),
        }

        return Message(text=json.dumps(resultado, ensure_ascii=False, indent=2))

from langflow.custom import Component
from langflow.io import StrInput, SecretStrInput, Output
from langflow.field_typing import Tool
from langchain.tools import Tool as LangchainTool
import requests
import time
import os
from concurrent.futures import ThreadPoolExecutor, as_completed


class NoticiasBVLToolComponent(Component):
    display_name = "Noticias BVL Tool"
    description = "Noticias del sector minero: Google News RSS + Alpha Vantage NEWS_SENTIMENT en paralelo."
    icon = "newspaper"
    name = "NoticiasBVLTool"

    inputs = [
        SecretStrInput(
            name="api_key",
            display_name="Alpha Vantage API Key",
            required=False,
        ),
    ]

    outputs = [
        Output(display_name="Tool", name="tool_output", method="build_tool"),
    ]

    def build_tool(self) -> Tool:
        api_key = self.api_key or os.environ.get("ALPHA_VANTAGE_KEY", "")

        def _fetch_news_ticker(ticker: str) -> list:
            for attempt in range(3):
                try:
                    url = (
                        "https://www.alphavantage.co/query"
                        "?function=NEWS_SENTIMENT&tickers=" + ticker + "&limit=15&apikey=" + api_key
                    )
                    r = requests.get(url, timeout=15)
                    r.raise_for_status()
                    data = r.json()
                    if data.get("Information") or data.get("Note"):
                        if attempt < 2:
                            time.sleep(15)
                            continue
                        return []
                    feed = data.get("feed", [])
                    relevant = []
                    for art in feed:
                        for ts_item in art.get("ticker_sentiment", []):
                            if ts_item.get("ticker") == ticker:
                                rel = float(ts_item.get("relevance_score", 0))
                                if rel >= 0.05:
                                    art2 = dict(art)
                                    art2["_rel"] = rel
                                    art2["_ts"] = float(ts_item.get("ticker_sentiment_score", 0))
                                    relevant.append(art2)
                                break
                    return relevant if relevant else feed
                except Exception:
                    if attempt < 2:
                        time.sleep(5)
            return []

        def _fetch_google_news_rss(query: str) -> list:
            """Titulares en espanol desde Google News RSS."""
            try:
                import feedparser
                encoded = requests.utils.quote(query)
                rss_url = (
                    "https://news.google.com/rss/search?q="
                    + encoded
                    + "&hl=es-419&gl=PE&ceid=PE:es-419"
                )
                feed = feedparser.parse(rss_url)
                articles = []
                for entry in (feed.entries or [])[:10]:
                    articles.append({
                        "title": entry.get("title", "Sin titulo"),
                        "link": entry.get("link", ""),
                        "published": entry.get("published", ""),
                        "summary": entry.get("summary", "")[:200],
                        "_source": "Google News",
                    })
                return articles
            except Exception:
                return []

        def buscar_noticias(input_text: str = "") -> str:
            text_lower = input_text.lower()
            if "scco" in text_lower or "southern" in text_lower or "copper" in text_lower or "cobre" in text_lower:
                primary, secondary = "SCCO", "BVN"
                rss_query = "Southern Copper Peru minera"
            elif "buenaventura" in text_lower or "bvn" in text_lower or "oro" in text_lower:
                primary, secondary = "BVN", "SCCO"
                rss_query = "Buenaventura minera Peru oro"
            else:
                primary, secondary = "BVN", "SCCO"
                rss_query = "mineras Peru BVL bolsa valores"

            av_articles = []
            rss_articles = []

            with ThreadPoolExecutor(max_workers=2) as executor:
                fut_av  = executor.submit(_fetch_news_ticker, primary)
                fut_rss = executor.submit(_fetch_google_news_rss, rss_query)
                for fut in as_completed([fut_av, fut_rss], timeout=30):
                    if fut is fut_av:
                        av_articles = fut.result() or []
                    else:
                        rss_articles = fut.result() or []

            if not av_articles:
                av_articles = _fetch_news_ticker(secondary)
                if av_articles:
                    primary = secondary

            NL = "\n"
            resultado = []

            if av_articles:
                alcistas = bajistas = neutros = 0
                lineas_av = []
                for i, art in enumerate(av_articles[:6], 1):
                    titulo = art.get("title", "Sin titulo")
                    fecha = art.get("time_published", "")[:8]
                    if len(fecha) == 8:
                        fecha = fecha[:4] + "-" + fecha[4:6] + "-" + fecha[6:8]
                    fuente = art.get("source", "Desconocida")
                    score = float(art.get("overall_sentiment_score", 0))
                    label = art.get("overall_sentiment_label", "Neutral")
                    ts_score = art.get("_ts", score)
                    resumen = art.get("summary", "")[:160]
                    if score > 0.15:
                        alcistas += 1
                    elif score < -0.15:
                        bajistas += 1
                    else:
                        neutros += 1
                    lineas_av.append(
                        "[" + str(i) + "] " + titulo + NL
                        + "    Fecha: " + fecha + " | Fuente: " + fuente + NL
                        + "    Sentimiento: " + label + " (" + ("+" if score >= 0 else "") + str(round(score, 3)) + ")"
                        + " | Score ticker: " + ("+" if ts_score >= 0 else "") + str(round(ts_score, 3)) + NL
                        + "    " + resumen
                    )
                total = alcistas + bajistas + neutros
                tendencia = "ALCISTA" if alcistas > bajistas else ("BAJISTA" if bajistas > alcistas else "NEUTRAL")
                resultado.append(
                    "=== NOTICIAS FINANCIERAS (Alpha Vantage) ===" + NL
                    + "TICKER: " + primary + " | " + str(total) + " noticias analizadas" + NL
                    + "Alcistas: " + str(alcistas) + " | Bajistas: " + str(bajistas) + " | Neutras: " + str(neutros) + NL
                    + "Tendencia dominante: " + tendencia + NL
                )
                resultado.append((NL + NL).join(lineas_av))

            if rss_articles:
                resultado.append(NL + "=== NOTICIAS EN ESPANOL (Google News) ===")
                for i, art in enumerate(rss_articles[:5], 1):
                    resultado.append(
                        "[" + str(i) + "] " + art.get("title", "Sin titulo") + NL
                        + "    Publicado: " + art.get("published", "?") + NL
                        + "    " + art.get("summary", "")[:160]
                    )

            if not resultado:
                return "No se encontraron noticias recientes. Usa score=0 y confianza=0."

            return NL.join(resultado)

        return LangchainTool(
            name="buscar_noticias_bvl",
            description=(
                "Busca noticias financieras y sentimiento del mercado para acciones mineras BVL. "
                "Combina Alpha Vantage NEWS_SENTIMENT (con scores de sentimiento) y Google News RSS (en espanol). "
                "Input: nombre de empresa o ticker (BVN, SCCO, Buenaventura, Southern Copper). "
                "SIEMPRE llama esta herramienta antes de dar tu analisis."
            ),
            func=buscar_noticias,
        )

from langflow.custom import Component
from langflow.io import SecretStrInput, Output
from langflow.field_typing import Tool
from langchain.tools import Tool as LangchainTool
import requests
import os


class DatosCommoditiesToolComponentV2(Component):
    display_name = "Datos Commodities Tool"
    description = "Precios, variacion diaria y tendencia 5d de oro, plata y cobre."
    icon = "trending-up"
    name = "DatosCommoditiesTool"

    inputs = [
        SecretStrInput(name="api_key", display_name="Twelve Data API Key", required=False),
        SecretStrInput(name="av_key",  display_name="Alpha Vantage API Key", value="TPTUYCIWJ2JYRVWQ"),
    ]
    outputs = [Output(display_name="Tool", name="tool_output", method="build_tool")]

    def build_tool(self) -> Tool:
        td_key = self.api_key or os.environ.get("TWELVE_DATA_KEY", "e81a8f3d635e4f8aac10cd2230d43e0c")
        av_key = self.av_key or os.environ.get("ALPHA_VANTAGE_KEY", "TPTUYCIWJ2JYRVWQ")

        def _formato_metal(nombre, simbolo, precio_hoy, precio_ayer, precio_5d, unidad="oz"):
            if None in (precio_hoy, precio_ayer):
                return "\n" + nombre + ": Sin datos suficientes"
            cambio_dia = (precio_hoy - precio_ayer) / precio_ayer * 100
            tend_5d = ((precio_hoy - precio_5d) / precio_5d * 100) if precio_5d else cambio_dia
            dir_dia = "sube" if cambio_dia > 0 else ("baja" if cambio_dia < 0 else "estable")
            dir_5d  = "positiva" if tend_5d > 0 else ("negativa" if tend_5d < 0 else "plana")
            return (
                "\n" + nombre + " (" + simbolo + "): $" + f"{precio_hoy:.2f}" + " USD/" + unidad
                + "\n  Cambio diario: " + f"{cambio_dia:+.2f}%" + " (" + dir_dia + ")"
                + "\n  Tendencia 5d:  " + f"{tend_5d:+.2f}%" + " (" + dir_5d + ")"
            )

        def _yfinance_metal(symbol):
            """Obtiene precio actual y serie reciente usando yfinance (sin API key)."""
            try:
                import yfinance as yf
                ticker = yf.Ticker(symbol)
                hist = ticker.history(period="10d")
                if hist.empty or len(hist) < 2:
                    return None
                closes = hist["Close"].dropna()
                if len(closes) < 2:
                    return None
                return {
                    "precio_hoy": float(closes.iloc[-1]),
                    "precio_ayer": float(closes.iloc[-2]),
                    "precio_5d": float(closes.iloc[-5]) if len(closes) >= 5 else float(closes.iloc[0]),
                }
            except Exception:
                return None

        def _twelve_data_metal(symbol, outputsize=6):
            """Fallback Twelve Data para oro y plata."""
            try:
                r = requests.get(
                    "https://api.twelvedata.com/time_series"
                    "?symbol=" + symbol + "&interval=1day&outputsize=" + str(outputsize) + "&apikey=" + td_key,
                    timeout=10,
                )
                values = r.json().get("values", [])
                if len(values) < 2:
                    return None
                return {
                    "precio_hoy": float(values[0]["close"]),
                    "precio_ayer": float(values[1]["close"]),
                    "precio_5d": float(values[min(4, len(values) - 1)]["close"]),
                }
            except Exception:
                return None

        def _alpha_vantage_cobre():
            """Fallback cobre mensual desde Alpha Vantage."""
            try:
                r = requests.get(
                    "https://www.alphavantage.co/query?function=COPPER&interval=monthly&apikey=" + av_key,
                    timeout=10,
                )
                d = r.json()
                if d.get("Information") or d.get("Note"):
                    return None, "Rate limit Alpha Vantage"
                data_pts = d.get("data", [])
                if len(data_pts) < 2:
                    return None, "Sin datos"
                precio_ton = float(data_pts[0]["value"])
                precio_ant = float(data_pts[1]["value"])
                precio_3m  = float(data_pts[2]["value"]) if len(data_pts) >= 3 else precio_ant
                return {
                    "precio_hoy": precio_ton / 2204.62,
                    "precio_ayer": precio_ant / 2204.62,
                    "precio_5d": precio_3m / 2204.62,
                    "fecha": data_pts[0]["date"],
                    "precio_ton": precio_ton,
                }, None
            except Exception as e:
                return None, str(e)

        def obtener_datos_commodities(input_text: str = "") -> str:
            resultado = ["=== PRECIOS COMMODITIES ==="]

            # ORO (GC=F): yfinance -> Twelve Data
            try:
                d = _yfinance_metal("GC=F")
                if d:
                    linea = _formato_metal("Oro", "XAU/USD", d["precio_hoy"], d["precio_ayer"], d["precio_5d"])
                    resultado.append(linea + " [yfinance]")
                else:
                    d = _twelve_data_metal("XAU/USD")
                    if d:
                        linea = _formato_metal("Oro", "XAU/USD", d["precio_hoy"], d["precio_ayer"], d["precio_5d"])
                        resultado.append(linea + " [Twelve Data]")
                    else:
                        resultado.append("\nOro: Sin datos disponibles")
            except Exception as e:
                resultado.append("\nOro: Error - " + str(e))

            # PLATA (SI=F): yfinance -> Twelve Data
            try:
                d = _yfinance_metal("SI=F")
                if d:
                    linea = _formato_metal("Plata", "XAG/USD", d["precio_hoy"], d["precio_ayer"], d["precio_5d"])
                    resultado.append(linea + " [yfinance]")
                else:
                    d = _twelve_data_metal("XAG/USD")
                    if d:
                        linea = _formato_metal("Plata", "XAG/USD", d["precio_hoy"], d["precio_ayer"], d["precio_5d"])
                        resultado.append(linea + " [Twelve Data]")
                    else:
                        resultado.append("\nPlata: Sin datos disponibles")
            except Exception as e:
                resultado.append("\nPlata: Error - " + str(e))

            # COBRE (HG=F): yfinance -> Alpha Vantage
            try:
                d = _yfinance_metal("HG=F")
                if d:
                    # HG=F cotiza en USD/lb directamente
                    linea = _formato_metal("Cobre", "HG=F", d["precio_hoy"], d["precio_ayer"], d["precio_5d"], unidad="lb")
                    resultado.append(linea + " [yfinance]")
                else:
                    d_av, err = _alpha_vantage_cobre()
                    if d_av:
                        linea = _formato_metal("Cobre", "LME", d_av["precio_hoy"], d_av["precio_ayer"], d_av["precio_5d"], unidad="lb")
                        resultado.append(linea + " [Alpha Vantage - " + d_av.get("fecha", "") + "]")
                    else:
                        resultado.append("\nCobre: " + (err or "Sin datos"))
            except Exception as e:
                resultado.append("\nCobre: Error - " + str(e))

            resultado.append(
                "\n\nContexto BVL:"
                "\n- BVN (Buenaventura): commodity principal = Oro"
                "\n- SCCO (Southern Copper): commodity principal = Cobre"
                "\n- Mineras polimetalicas (Minsur, Volcan, El Brocal): Plata y Zinc tambien relevantes"
            )
            return "\n".join(resultado)

        return LangchainTool(
            name="obtener_datos_commodities",
            description=(
                "Obtiene precio actual, variacion diaria y tendencia de commodities: "
                "Oro (XAU/USD via GC=F), Plata (XAG/USD via SI=F) y Cobre (HG=F). "
                "Relevante para BVN (oro), SCCO (cobre) y mineras polimetalicas (plata). "
                "Input: cualquier texto."
            ),
            func=obtener_datos_commodities,
        )
